Extensions.ExtractScript:
param(
    [xml] $Document
);
foreach( $file in $Document.unattend.Extensions.File ) {
    $path = [System.Environment]::ExpandEnvironmentVariables( $file.GetAttribute( 'path' ) );
    mkdir -Path( $path | Split-Path -Parent ) -ErrorAction 'SilentlyContinue';
    $encoding = switch( [System.IO.Path]::GetExtension( $path ) ) {
        { $_ -in '.ps1', '.xml' } { [System.Text.Encoding]::UTF8; }
        { $_ -in '.reg', '.vbs', '.js' } { [System.Text.UnicodeEncoding]::new( $false, $true ); }
        default { [System.Text.Encoding]::Default; }
    };
    $bytes = $encoding.GetPreamble() + $encoding.GetBytes( $file.InnerText.Trim() );
    [System.IO.File]::WriteAllBytes( $path, $bytes );
}

Extensions.File:
# Waits for network, joins the domain, assigns PXE computer name from shared counter file.
# Fill in placeholders before deployment.

$maxAttempts = 5
$attempt = 0
while ($attempt -lt $maxAttempts) {
    $attempt++
    ipconfig /renew | Out-Null
    if (Test-Connection -ComputerName 8.8.8.8 -Count 1 -Quiet) { break }
    if ($attempt -lt $maxAttempts) { Start-Sleep -Seconds 5 }
}

$domain     = ""
$username   = "\"
$password   = ConvertTo-SecureString "" -AsPlainText -Force
$credential = New-Object System.Management.Automation.PSCredential($username, $password)

$networkPath = "\\\deploymentshare$"
New-PSDrive -Name "Z" -PSProvider "FileSystem" -Root $networkPath -Credential $credential -ErrorAction SilentlyContinue
$numberFile = "Z:\Applications\Number.txt"

$number = 0
if (Test-Path $numberFile) { $number = [int](Get-Content $numberFile -Raw).Trim() }
$number += 1
Set-Content -Path $numberFile -Value $number -NoNewline
$newName = "PXE$number"

$maxRetries = 3
$retryCount = 0
$success    = $false

while ($retryCount -lt $maxRetries -and -not $success) {
    try {
        Add-Computer -DomainName $domain -NewName $newName -Credential $credential -OUPath "" -Force -ErrorAction Stop
        $success = $true
    }
    catch {
        if ($_.Exception.Message -like "*busy*" -or $_.Exception.Message -like "*ausgelastet*" -or $_.Exception.HResult -eq 0x200E) {
            Start-Sleep -Seconds 30
            $retryCount++
        } else { throw }
    }
}

if (-not $success) {
    Start-Sleep -Seconds 10
    Restart-Computer -Force
} else {
    netsh advfirewall set domainprofile state off
    powercfg -change -standby-timeout-ac 0
    powercfg -change -hibernate-timeout-ac 0
    Start-Sleep -Seconds 10
    Restart-Computer -Force
}
